/**
 * Integration test on the bundled sample images (synthetic, generated by
 * scripts/generate-sample-photos.mjs): JPEG decode → 128px area downscale → metrics →
 * signature → grouping → recommendation. Mirrors the app pipeline except the native resize.
 */
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import * as jpeg from 'jpeg-js';

import type { PhotoAsset } from '@/domain/models';
import { groupDuplicates } from '@/features/image-analysis/duplicate-analyzer';
import { lumaSignature } from '@/features/image-analysis/perceptual-hash';
import { computeQualityMetrics, type RgbaImage } from '@/features/image-analysis/pixel-metrics';
import { defaultPreference } from '@/features/onboarding/preference-schema';
import { orientationOf } from '@/features/photo-import/asset-normalizer';
import { recommend } from '@/features/recommendations/engine';
import { technicalQuality } from '@/features/recommendations/scoring';

function loadSample(n: number): { img: RgbaImage; ow: number; oh: number } {
  const d = jpeg.decode(readFileSync(join(__dirname, '..', '..', 'assets', 'samples', `sample-${String(n).padStart(2, '0')}.jpg`)), { useTArray: true });
  const s = 128 / Math.max(d.width, d.height);
  const w = Math.round(d.width * s);
  const h = Math.round(d.height * s);
  const out = new Uint8Array(w * h * 4);
  for (let y = 0; y < h; y++)
    for (let x = 0; x < w; x++) {
      const x0 = Math.floor(x / s), x1 = Math.min(d.width, Math.floor((x + 1) / s));
      const y0 = Math.floor(y / s), y1 = Math.min(d.height, Math.floor((y + 1) / s));
      const acc = [0, 0, 0];
      let c = 0;
      for (let yy = y0; yy < y1; yy++)
        for (let xx = x0; xx < x1; xx++) {
          const i = (yy * d.width + xx) * 4;
          acc[0] += d.data[i]; acc[1] += d.data[i + 1]; acc[2] += d.data[i + 2];
          c++;
        }
      const o = (y * w + x) * 4;
      out[o] = acc[0] / c; out[o + 1] = acc[1] / c; out[o + 2] = acc[2] / c; out[o + 3] = 255;
    }
  return { img: { width: w, height: h, data: out }, ow: d.width, oh: d.height };
}

const N = 18;
const photos: PhotoAsset[] = Array.from({ length: N }, (_, i) => {
  const { img, ow, oh } = loadSample(i + 1);
  return {
    id: String(i + 1),
    projectId: 'sample',
    localUri: `asset://sample-${i + 1}`,
    width: ow,
    height: oh,
    orientation: orientationOf(ow, oh),
    sceneTags: [],
    analysisStatus: 'done',
    importIndex: i,
    perceptualHash: lumaSignature(img),
    qualityMetrics: computeQualityMetrics({ image: img, originalWidth: ow, originalHeight: oh }),
  };
});

describe('bundled sample images', () => {
  const groups = groupDuplicates(photos.map((p) => ({ id: p.id, hash: p.perceptualHash, meanRgb: p.qualityMetrics!.meanRgb, quality: technicalQuality(p.qualityMetrics!) })));

  it('groups exactly the generated near-duplicates', () => {
    const sets = groups.map((g) => [...g.memberIds].sort((a, b) => +a - +b).join(',')).sort();
    expect(sets).toEqual(['1,2,3', '4,5', '9,17']);
  });

  it('never picks the blurred copy as representative', () => {
    const g = groups.find((x) => x.memberIds.includes('3'))!;
    expect(g.representativeId).not.toBe('3');
  });

  it('blurred and overexposed variants get lower technical signals', () => {
    const m = (id: string) => photos.find((p) => p.id === id)!.qualityMetrics!;
    expect(m('3').sharpnessScore).toBeLessThan(m('1').sharpnessScore);
    expect(m('7').exposureScore).toBeLessThan(m('1').exposureScore);
  });

  it('a 9:16 story set avoids heavy landscape crops when portrait photos are available', () => {
    const grouped = photos.map((p) => ({ ...p, duplicateGroupId: groups.find((x) => x.memberIds.includes(p.id))?.id ?? null }));
    const out = recommend({
      photos: grouped,
      purposeId: 'instagram-story',
      targetCount: 3,
      presetId: 'travel-photodump',
      preference: defaultPreference(),
      learned: null,
      pinnedIds: [],
      excludedIds: [],
      groupRepresentatives: {},
    });
    const chosen = out.orderedIds.map((id) => photos.find((p) => p.id === id)!);
    expect(chosen.every((p) => p.orientation !== 'landscape')).toBe(true);
  });

  it('a 6-photo carousel contains at most one photo per duplicate group', () => {
    const grouped = photos.map((p) => {
      const g = groups.find((x) => x.memberIds.includes(p.id));
      return { ...p, duplicateGroupId: g?.id ?? null };
    });
    const out = recommend({
      photos: grouped,
      purposeId: 'instagram-carousel',
      targetCount: 6,
      presetId: 'travel-photodump',
      preference: defaultPreference(),
      learned: null,
      pinnedIds: [],
      excludedIds: [],
      groupRepresentatives: {},
    });
    expect(out.orderedIds).toHaveLength(6);
    for (const g of groups) {
      expect(out.orderedIds.filter((id) => g.memberIds.includes(id)).length).toBeLessThanOrEqual(1);
    }
  });
});
